import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"TabDisplay","description":"","frontmatter":{"navigation":{"category":"Gameplay"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/tab-display/docs/index.md"},"headers":[],"relativePath":"packages/tab-display/docs/index.md","filePath":"packages/tab-display/docs/index.md","lastUpdated":1792508965000}`),l={name:`packages/tab-display/docs/index.md`},u={id:`tabdisplay`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/tab-display/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`TabDisplay `),n(`a`,{class:`header-anchor`,href:`#tabdisplay`,"aria-label":`Permalink to “TabDisplay”`},`​`)],-1),n(`span`,d,[a(h,{type:`info`,text:`v0.0.0`})])]),c[2]||=r(`<p>TabDisplay formats the Java player list: it gives every listed player&#39;s name the same template and style, and shows each Java player their own header and footer lines. Bedrock players keep Pumpkin&#39;s normal player list.</p><p>Install <code>tab-display.wasm</code> in the server&#39;s <code>plugins/</code> directory and restart. TabDisplay creates <code>plugins/data/TabDisplay/config.toml</code> on the first start. It needs <code>fs.read.data</code> and <code>fs.write.data</code> for that file, and <code>http.outbound</code> for the usual Pumpkin Market update check.</p><h2 id="what-it-changes" tabindex="-1">What it changes <a class="header-anchor" href="#what-it-changes" aria-label="Permalink to “What it changes”">​</a></h2><table tabindex="0"><thead><tr><th>Part of the player list</th><th>What TabDisplay does</th></tr></thead><tbody><tr><td>Java row names</td><td>Applies <code>entry.text</code> and its style to every listed player</td></tr><tr><td>Java header and footer</td><td>Renders <code>header.lines</code> and <code>footer.lines</code> for each viewer</td></tr><tr><td>Bedrock player list</td><td>Leaves it unchanged</td></tr></tbody></table><p>TabDisplay doesn&#39;t sort the list, add score columns, add fake rows or show different row names to different viewers. It never changes player identities, skins or who appears in the list.</p><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to “Placeholders”">​</a></h2><p>Templates can contain tokens such as <code>%player_name%</code>. Without any other plugin, TabDisplay fills in two of them itself: <code>%player_name%</code> and <code>%server_online%</code>, the number of players online. That covers the default config, so a fresh install shows real names and counts.</p><p>Every other token needs <a href="https://github.com/Rennex07/PumpkinPIE/releases" target="_blank" rel="noreferrer">PumpkinPIE</a>, a separate plugin that TabDisplay doesn&#39;t bundle. Install a PumpkinPIE release built for your Pumpkin version next to TabDisplay. <code>placeholders.provider</code> is the plugin name TabDisplay asks for values.</p><p>While PumpkinPIE isn&#39;t running, <code>placeholders.missing_provider</code> decides what the other tokens show: <code>literal</code> leaves the token text in place and <code>empty</code> removes it. Tokens PumpkinPIE doesn&#39;t know follow <code>placeholders.unresolved</code> in the same way.</p><p>Header and footer tokens are filled in for the player looking at the list. Row-name tokens are filled in for the player in that row. Placeholder values are always shown as plain text, so a value can&#39;t add formatting or clickable commands.</p><p>If PumpkinPIE stops answering, TabDisplay keeps showing the last complete result for up to 30 seconds, then switches to the fallback text above.</p><h2 id="commands-and-config-changes" tabindex="-1">Commands and config changes <a class="header-anchor" href="#commands-and-config-changes" aria-label="Permalink to “Commands and config changes”">​</a></h2><p>The <code>/tabdisplay</code> commands are for operators by default:</p><ul><li><code>/tabdisplay status</code> shows whether PumpkinPIE is connected, how many Java and Bedrock players are online, their Java versions, unknown placeholder tokens and the last problem TabDisplay hit.</li><li><code>/tabdisplay reload</code> applies changes to <code>config.toml</code>. If the file has invalid TOML or an invalid value, the reload lists the problems and keeps the current settings.</li><li><code>/tabdisplay inspect &lt;player&gt;</code> shows which placeholder tokens apply to one player. It doesn&#39;t show their values.</li></ul><p>At startup, an invalid value falls back to its default and TabDisplay logs a warning; if the file isn&#39;t valid TOML, every setting uses its default. TabDisplay never rewrites a file that has invalid values, so your edits stay in place for you to fix.</p><h2 id="turning-it-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-it-off" aria-label="Permalink to “Turning it off”">​</a></h2><p>Set <code>general.enabled = false</code> and reload to undo all of TabDisplay&#39;s changes for online players, or set <code>entry.enabled = false</code> to undo only the row names. Unloading the plugin undoes them too. A row name goes back to what it was before TabDisplay changed it, unless another plugin has changed it since; that newer name is left alone. Pumpkin has no way to read the previous header and footer, so TabDisplay clears them.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><p>TabDisplay refreshes the list every <code>general.refresh_ticks</code> ticks, 20 by default. It works on at most <code>general.max_players</code> online players, 500 by default and 5,000 at most. When more players are online than that, it stops updating and logs a warning, then logs again and carries on once the count drops.</p><p>Each tick sends PumpkinPIE at most one batch of 256 placeholder requests, and no batch is larger than 1 MiB. A rendered line longer than 8 KiB is cut to fit. These limits keep each tick&#39;s work bounded, but nobody has measured their effect on server TPS yet.</p>`,20)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};